// SPDX-License-Identifier: BSD-2-Clause-Patent
// Called by bsd_init in place of its IOKitBSDInit call in the boot candidate.
#include <IOKit/IOLib.h>
#include <pexpert/pexpert.h>
extern "C" int IOKitBSDInit(void);
extern "C" int myron_ufs_register_classes(void);
extern "C" void myron_ufs_probe(void);
extern "C" {
volatile unsigned myron_storage_boot_claimed = 0;
volatile unsigned myron_storage_boot_stage = 0;
volatile int myron_storage_boot_status = kIOReturnNotReady;
}

extern "C" int myron_storage_iokit_bsd_init(void)
{
    // Publish IOBSD and complete the original initialization first. Preserve
    // its return value: an optional diagnostic must not mask a BSD failure.
    int result = IOKitBSDInit();
    if (result) return result;
    unsigned mode = 0;
    if (!PE_parse_boot_argn("myron27-storage", &mode, sizeof(mode)) ||
        (mode != 1 && mode != 2)) return result;
    if (!__sync_bool_compare_and_swap(&myron_storage_boot_claimed, 0U, 1U))
        return result;
    myron_storage_boot_stage = 1;
    int status = myron_ufs_register_classes();
    myron_storage_boot_status = status;
    IOLog("myron27 storage: registration 0x%x, mode %u\n", status, mode);
    if (status) { myron_storage_boot_stage = 2; return result; }
    myron_storage_boot_stage = 3;
    if (mode == 2) {
        // The existing bounded transport/GPT probe owns its hardware checks.
        // MYRON_ROOT_POLICY and MYRON_ROOT_BOOT remain zero in this candidate.
        myron_storage_boot_stage = 4;
        myron_ufs_probe();
        myron_storage_boot_stage = 5;
        IOLog("myron27 storage: transport probe returned; inspect myron_ufs_report\n");
    }
    return result;
}

