// SPDX-License-Identifier: BSD-2-Clause-Patent
// Explicit boot-thread entry, called only after the IOKit/kext runtime exists.
// This registers classes; it never starts a service or accesses hardware.
#include <IOKit/IOService.h>
#include <libkern/OSKextLib.h>
#include <libkern/c++/OSSymbol.h>
#include <mach/kmod.h>
extern kmod_info_t g_kernel_kmod_info;
extern "C" void myron_storage_static_init(void)
    __asm__("__GLOBAL__sub_I_MyronUfsProbe.cpp");
extern "C" const char myron_original_storage_meta[]
    __asm__("__ZN20IOBlockStorageDevice10gMetaClassE");
extern "C" {
volatile unsigned myron_storage_registration_state = 0;
volatile int myron_storage_registration_status = kIOReturnNotReady;
}

static const OSMetaClass *lookup(const char *text)
{
    const OSSymbol *name = OSSymbol::withCString(text);
    const OSMetaClass *result = name ? OSMetaClass::getMetaClassWithName(name) : nullptr;
    if (name) name->release();
    return result;
}

extern "C" int myron_ufs_register_classes(void)
{
    // Claim once, including failures. Re-running constructors can panic on iOS.
    // Callers must not unload these kernel-owned classes during this boot.
    if (!__sync_bool_compare_and_swap(&myron_storage_registration_state, 0U, 1U))
        return myron_storage_registration_status;
    int status = OSKextLoadKextWithIdentifier("com.apple.iokit.IOStorageFamily");
    if (status) {
        myron_storage_registration_status = status;
        return status;
    }
    const OSMetaClass *parent = lookup("IOBlockStorageDevice");
    const OSMetaClass *service = lookup("IOService");
    if (!parent || !service || reinterpret_cast<const void *>(parent) != myron_original_storage_meta ||
        parent->getClassSize() != 0x90 || service->getClassSize() != 0x88 ||
        parent->getSuperClass() != service) {
        myron_storage_registration_status = kIOReturnUnsupported;
        return kIOReturnUnsupported;
    }
    if (lookup("NativeUfs") || lookup("NativeUfsBlock")) {
        myron_storage_registration_status = kIOReturnExclusiveAccess;
        return kIOReturnExclusiveAccess;
    }
    myron_storage_registration_state = 2;
    // Use the existing kernel OSKext owner; an invented identifier fails
    // postModLoad with kOSMetaClassNoKext even when constructors succeeded.
    void *handle = OSMetaClass::preModLoad(g_kernel_kmod_info.name);
    if (!handle) {
        myron_storage_registration_status = kIOReturnNoMemory;
        return kIOReturnNoMemory;
    }
    myron_storage_static_init();
    status = OSMetaClass::postModLoad(handle); // always releases the registration context
    if (!status) {
        const OSMetaClass *ufs = lookup("NativeUfs");
        const OSMetaClass *block = lookup("NativeUfsBlock");
        if (!ufs || !block || ufs->getSuperClass() != service || block->getSuperClass() != parent)
            status = kIOReturnUnsupported;
    }
    myron_storage_registration_status = status;
    __sync_synchronize();
    myron_storage_registration_state = status ? 3U : 4U;
    return status;
}

