// SPDX-License-Identifier: BSD-2-Clause-Patent
#ifndef DARWINBOOT_KERNEL_STREAM_H
#define DARWINBOOT_KERNEL_STREAM_H

#define KERNEL_HEADER_LIMIT SIZE_64KB
#define KERNEL_READ_CHUNK   SIZE_64KB

STATIC
EFI_STATUS
ReadKernelAt (EFI_FILE_PROTOCOL *File, UINTN FileSize, UINT64 Offset, UINTN Size, VOID *Buffer)
{
  EFI_STATUS Status;
  UINTN Done;
  UINTN Actual;
  UINTN Want;
  if ((File == NULL) || (Offset > FileSize) || (Size > FileSize - Offset) || ((Size != 0) && (Buffer == NULL))) {
    return EFI_BAD_BUFFER_SIZE;
  }
  if (Size == 0) { return EFI_SUCCESS; }
  Status = File->SetPosition (File, Offset);
  if (EFI_ERROR (Status)) { return Status; }
  Done = 0;
  while (Done < Size) {
    Want = MIN (Size - Done, KERNEL_READ_CHUNK);
    Actual = Want;
    Status = File->Read (File, &Actual, (UINT8 *)Buffer + Done);
    if (EFI_ERROR (Status)) { return Status; }
    if ((Actual == 0) || (Actual > Want)) { return EFI_DEVICE_ERROR; }
    Done += Actual;
  }
  return EFI_SUCCESS;
}

STATIC
EFI_STATUS
ParseKernelHeader (CONST UINT8 *Data, UINTN Size, UINTN FileSize, KERNEL *Kernel)
{
  UINTN    Offset;
  UINTN    End;
  UINTN    Index;
  UINTN    Other;
  UINT32   Count;
  UINT32   Command;
  UINT32   Length;
  SEGMENT  *Segment;
  BOOLEAN  HasEntry;
  BOOLEAN  Executable;

  if ((Size < 32) || (U32 (Data) != 0xfeedfacf) || (U32 (Data + 4) != 0x100000c) ||
      (((U32 (Data + 8) & 0x00ffffff) != 0) &&
       ((U32 (Data + 8) & 0x00ffffff) != 2)) ||
      ((U32 (Data + 12) != 2) && (U32 (Data + 12) != 12))) {
    return EFI_UNSUPPORTED;
  }
  if (U32 (Data + 20) > Size - 32) { return EFI_LOAD_ERROR; }
  ZeroMem (Kernel, sizeof (*Kernel));
  Count = U32 (Data + 16);
  End = 32 + U32 (Data + 20);
  Offset = 32;
  HasEntry = FALSE;
  for (Index = 0; Index < Count; Index++) {
    if (End - Offset < 8) { return EFI_LOAD_ERROR; }
    Command = U32 (Data + Offset);
    Length = U32 (Data + Offset + 4);
    if ((Length < 8) || (Length & 7) || (Length > End - Offset)) { return EFI_LOAD_ERROR; }
    if (Command == 0x19) {
      if ((Length < 72) || (((Length - 72) % 80) != 0) ||
          (U32 (Data + Offset + 64) != (Length - 72) / 80) ||
          (Kernel->Count == MAX_SEGMENTS)) { return EFI_LOAD_ERROR; }
      if (U64 (Data + Offset + 32) != 0) {
        Segment = &Kernel->Segments[Kernel->Count++];
        Segment->Address = U64 (Data + Offset + 24);
        Segment->Size = U64 (Data + Offset + 32);
        Segment->FileOffset = U64 (Data + Offset + 40);
        Segment->FileSize = U64 (Data + Offset + 48);
        Segment->Protection = U32 (Data + Offset + 60);
        if ((Segment->Size > WINDOW_SIZE) || (Segment->Address > MAX_UINT64 - Segment->Size) ||
            (Segment->FileSize > Segment->Size) || (Segment->FileOffset > FileSize) ||
            (Segment->FileSize > FileSize - Segment->FileOffset)) { return EFI_LOAD_ERROR; }
      }
    } else if (Command == 5) {
      if (HasEntry || (Length != 288) || (U32 (Data + Offset + 8) != 6) ||
          (U32 (Data + Offset + 12) != 68)) { return EFI_LOAD_ERROR; }
      Kernel->Entry = U64 (Data + Offset + 272);
      HasEntry = TRUE;
    }
    Offset += Length;
  }
  if ((Offset != End) || !HasEntry || (Kernel->Count == 0)) { return EFI_LOAD_ERROR; }
  Kernel->Base = MAX_UINT64;
  Executable = FALSE;
  for (Index = 0; Index < Kernel->Count; Index++) {
    Segment = &Kernel->Segments[Index];
    Kernel->Base = MIN (Kernel->Base, Segment->Address);
    Kernel->End = MAX (Kernel->End, Segment->Address + Segment->Size);
    if ((Kernel->Entry >= Segment->Address) && (Kernel->Entry - Segment->Address < Segment->FileSize) &&
        ((Segment->Protection & 4) != 0)) { Executable = TRUE; }
    for (Other = 0; Other < Index; Other++) {
      if ((Segment->Address < Kernel->Segments[Other].Address + Kernel->Segments[Other].Size) &&
          (Kernel->Segments[Other].Address < Segment->Address + Segment->Size)) { return EFI_LOAD_ERROR; }
    }
  }
  if (!Executable || (Kernel->Entry & 3) || (Kernel->Base & EFI_PAGE_MASK) ||
      (Kernel->Base > MAX_UINT64 - WINDOW_SIZE) ||
      (Kernel->End - Kernel->Base > WINDOW_SIZE - SIZE_2MB)) { return EFI_LOAD_ERROR; }
  return EFI_SUCCESS;
}
// Each header is bounded independently. Never allocate the whole collection.
STATIC
EFI_STATUS
ReadKernelHeaderAt (EFI_FILE_PROTOCOL *File, UINTN FileSize, UINT64 Offset,
                    UINT8 **HeaderOut, UINTN *SizeOut)
{
  EFI_STATUS Status;
  UINT8 First[32];
  UINT8 *Header;
  UINTN Size;
  *HeaderOut = NULL;
  *SizeOut = 0;
  Status = ReadKernelAt (File, FileSize, Offset, sizeof (First), First);
  if (EFI_ERROR (Status)) { return Status; }
  if ((U32 (First) != 0xfeedfacf) || (U32 (First + 4) != 0x100000c) ||
      (U32 (First + 20) > KERNEL_HEADER_LIMIT - sizeof (First)) ||
      (U32 (First + 20) > FileSize - Offset - sizeof (First))) { return EFI_LOAD_ERROR; }
  Size = sizeof (First) + U32 (First + 20);
  Header = AllocatePool (Size);
  if (Header == NULL) { return EFI_OUT_OF_RESOURCES; }
  CopyMem (Header, First, sizeof (First));
  Status = ReadKernelAt (File, FileSize, Offset + sizeof (First), Size - sizeof (First), Header + sizeof (First));
  if (EFI_ERROR (Status)) { FreePool (Header); return Status; }
  *HeaderOut = Header;
  *SizeOut = Size;
  return EFI_SUCCESS;
}

STATIC
BOOLEAN
KernelHeaderCovered (CONST KERNEL *Kernel, UINT64 FileOffset, UINT64 Address, UINTN Size)
{
  UINTN Index;
  CONST SEGMENT *Parent;
  for (Index = 0; Index < Kernel->Count; Index++) {
    Parent = &Kernel->Segments[Index];
    if ((FileOffset >= Parent->FileOffset) &&
        (FileOffset - Parent->FileOffset <= Parent->FileSize) &&
        (Size <= Parent->FileSize - (FileOffset - Parent->FileOffset)) &&
        (Address == Parent->Address + (FileOffset - Parent->FileOffset))) { return TRUE; }
  }
