// Fileset offsets are absolute in the collection. Only root mappings are
// copied. XNU retains responsibility for rebasing and signing its fixup chains.
// Root load commands have already been checked by ParseKernelHeader.
STATIC
EFI_STATUS
ValidateKernelFileset (EFI_FILE_PROTOCOL *File, UINTN FileSize, CONST UINT8 *Root,
                       UINTN RootSize, CONST KERNEL *Kernel)
{
  EFI_STATUS Status;
  KERNEL Member;
  UINTN Offset;
  UINTN Previous;
  UINTN Name;
  UINTN NameEnd;
  UINTN PreviousName;
  UINTN PreviousLength;
  UINTN Index;
  UINTN Other;
  UINTN ChildSize;
  UINTN ChildOffset;
  UINT32 Length;
  UINT32 ChildLength;
  UINT8 *Header;
  UINT64 HeaderOffset;
  UINT64 HeaderAddress;
  BOOLEAN Found;
  BOOLEAN Covered;
  BOOLEAN IsKernel;
  CONST SEGMENT *Child;
  CONST SEGMENT *Parent;

  Found = FALSE;
  for (Offset = 32; Offset < RootSize; Offset += Length) {
    Length = U32 (Root + Offset + 4);
    if (U32 (Root + Offset) != 0x80000035) { continue; }
    if (Length < 40) { return EFI_LOAD_ERROR; }
    Name = U32 (Root + Offset + 24);
    if ((Name < 32) || (Name >= Length)) { return EFI_LOAD_ERROR; }
    for (NameEnd = Name; (NameEnd < Length) && (Root[Offset + NameEnd] != 0); NameEnd++) {}
    if ((NameEnd == Name) || (NameEnd == Length)) { return EFI_LOAD_ERROR; }
    HeaderOffset = U64 (Root + Offset + 16);
    HeaderAddress = U64 (Root + Offset + 8);
    if ((HeaderOffset & 7) || !KernelHeaderCovered (Kernel, HeaderOffset, HeaderAddress, 32)) {
      return EFI_LOAD_ERROR;
    }
    // Reject ambiguous indexes before following any duplicate entry.
    for (Previous = 32; Previous < Offset; Previous += U32 (Root + Previous + 4)) {
      if (U32 (Root + Previous) != 0x80000035) { continue; }
      PreviousName = U32 (Root + Previous + 24);
      PreviousLength = U32 (Root + Previous + 4);
      if ((U64 (Root + Previous + 16) == HeaderOffset) ||
          (U64 (Root + Previous + 8) == HeaderAddress) ||
          ((NameEnd - Name + 1 <= PreviousLength - PreviousName) &&
           (CompareMem (Root + Previous + PreviousName, Root + Offset + Name, NameEnd - Name + 1) == 0))) {
        return EFI_LOAD_ERROR;
      }
    }
    Status = ReadKernelHeaderAt (File, FileSize, HeaderOffset, &Header, &ChildSize);
    if (EFI_ERROR (Status)) { return Status; }
    IsKernel = (NameEnd - Name == sizeof ("com.apple.kernel") - 1) &&
               (CompareMem (Root + Offset + Name, "com.apple.kernel", sizeof ("com.apple.kernel")) == 0);
    Status = EFI_LOAD_ERROR;
    if (!KernelHeaderCovered (Kernel, HeaderOffset, HeaderAddress, ChildSize) ||
        (U32 (Header + 8) != U32 (Root + 8)) ||
        (U32 (Header + 12) != (IsKernel ? 2U : 11U)) ||
        ((U32 (Header + 24) & 0x80000000) == 0)) { goto MemberDone; }
    // Validate every indexed member's command envelope, including kexts.
    ChildOffset = 32;
    for (Index = 0; Index < U32 (Header + 16); Index++) {
      if (ChildSize - ChildOffset < 8) { goto MemberDone; }
      ChildLength = U32 (Header + ChildOffset + 4);
      if ((ChildLength < 8) || (ChildLength & 7) || (ChildLength > ChildSize - ChildOffset)) { goto MemberDone; }
      ChildOffset += ChildLength;
    }
    if (ChildOffset != ChildSize) { goto MemberDone; }
    if (IsKernel) {
      if (Found) { goto MemberDone; }
      Found = TRUE;
      if (EFI_ERROR (ParseKernelHeader (Header, ChildSize, FileSize, &Member)) ||
          (Member.Entry != Kernel->Entry)) { goto MemberDone; }
      for (Index = 0; Index < Member.Count; Index++) {
        Child = &Member.Segments[Index];
        Covered = FALSE;
        for (Other = 0; Other < Kernel->Count; Other++) {
          Parent = &Kernel->Segments[Other];
          if ((Child->Address >= Parent->Address) &&
              (Child->Address - Parent->Address <= Parent->Size) &&
              (Child->Size <= Parent->Size - (Child->Address - Parent->Address)) &&
              ((Child->Protection & ~Parent->Protection) == 0) &&
              ((Child->FileSize == 0) ||
               ((Child->Address - Parent->Address <= Parent->FileSize) &&
                (Child->FileSize <= Parent->FileSize - (Child->Address - Parent->Address)) &&
                (Child->FileOffset == Parent->FileOffset + (Child->Address - Parent->Address))))) {
            Covered = TRUE;
          }
        }
        if (!Covered) { goto MemberDone; }
      }
    }
    Status = EFI_SUCCESS;
MemberDone:
    FreePool (Header);
    if (EFI_ERROR (Status)) { return Status; }
  }
  return Found ? EFI_SUCCESS : EFI_LOAD_ERROR;
}

STATIC
EFI_STATUS
OpenKernel (EFI_FILE_PROTOCOL *Root, CONST CHAR16 *Path, EFI_FILE_PROTOCOL **FileOut,
            UINTN *FileSize, KERNEL *Kernel)
{
  EFI_FILE_PROTOCOL *File;
  EFI_FILE_INFO *Info;
  EFI_STATUS Status;
  UINTN InfoSize;
  UINTN InfoCapacity;
  UINTN HeaderSize;
  UINT8 *Header;
  *FileOut = NULL;
  *FileSize = 0;
  Info = NULL;
  Header = NULL;
  Status = Root->Open (Root, &File, (CHAR16 *)Path, EFI_FILE_MODE_READ, 0);
  if (EFI_ERROR (Status)) { return Status; }
  InfoSize = 0;
  Status = File->GetInfo (File, &gEfiFileInfoGuid, &InfoSize, NULL);
  if ((Status != EFI_BUFFER_TOO_SMALL) || (InfoSize < SIZE_OF_EFI_FILE_INFO) || (InfoSize > SIZE_64KB)) {
    if (!EFI_ERROR (Status) || (Status == EFI_BUFFER_TOO_SMALL)) { Status = EFI_COMPROMISED_DATA; }
    goto Done;
  }
  InfoCapacity = InfoSize;
  Info = AllocatePool (InfoCapacity);
  if (Info == NULL) { Status = EFI_OUT_OF_RESOURCES; goto Done; }
  Status = File->GetInfo (File, &gEfiFileInfoGuid, &InfoSize, Info);
  if (EFI_ERROR (Status)) { goto Done; }
  if ((InfoSize < SIZE_OF_EFI_FILE_INFO) || (InfoSize > InfoCapacity) ||
      (Info->Size < SIZE_OF_EFI_FILE_INFO) || (Info->Size > InfoSize) ||
      (Info->Attribute & EFI_FILE_DIRECTORY) || (Info->FileSize < 32) || (Info->FileSize > SIZE_128MB)) {
    Status = EFI_BAD_BUFFER_SIZE; goto Done;
  }
  *FileSize = (UINTN)Info->FileSize;
  Status = ReadKernelHeaderAt (File, *FileSize, 0, &Header, &HeaderSize);
  if (EFI_ERROR (Status)) { goto Done; }
  Status = ParseKernelHeader (Header, HeaderSize, *FileSize, Kernel);
  if (!EFI_ERROR (Status) && (U32 (Header + 12) == 12)) {
    Status = ValidateKernelFileset (File, *FileSize, Header, HeaderSize, Kernel);
  }
  if (!EFI_ERROR (Status)) {
    *FileOut = File;
    Print (L"DARWINBOOT: streaming kernel bytes=%lu header=%lu chunk=%u\n",
           (UINT64)*FileSize, (UINT64)HeaderSize, (UINT32)KERNEL_READ_CHUNK);
  }
Done:
  if (Info != NULL) { FreePool (Info); }
  if (Header != NULL) { FreePool (Header); }
  if (*FileOut == NULL) { File->Close (File); }
  return Status;
}

STATIC
EFI_STATUS
StreamKernel (EFI_FILE_PROTOCOL *File, UINTN FileSize, CONST KERNEL *Kernel,
              EFI_PHYSICAL_ADDRESS Address, UINT64 Capacity)
{
  EFI_STATUS Status;
  UINTN Index;
  CONST SEGMENT *Segment;
  if ((File == NULL) || (Kernel->Count == 0) || (Kernel->Count > MAX_SEGMENTS) ||
      (Kernel->End < Kernel->Base) || (Kernel->End - Kernel->Base > Capacity) ||
      (Address > MAX_UINTN) || (Capacity > MAX_UINTN - Address)) { return EFI_BAD_BUFFER_SIZE; }
  // Validate all ranges before the first destination write.
  for (Index = 0; Index < Kernel->Count; Index++) {
    Segment = &Kernel->Segments[Index];
    if ((Segment->Address < Kernel->Base) || (Segment->Address - Kernel->Base > Capacity) ||
        (Segment->Size > Capacity - (Segment->Address - Kernel->Base)) ||
        (Segment->FileSize > Segment->Size) || (Segment->FileOffset > FileSize) ||
        (Segment->FileSize > FileSize - Segment->FileOffset)) { return EFI_BAD_BUFFER_SIZE; }
  }
  for (Index = 0; Index < Kernel->Count; Index++) {
    Segment = &Kernel->Segments[Index];
    Status = ReadKernelAt (File, FileSize, Segment->FileOffset, (UINTN)Segment->FileSize,
                          (VOID *)(UINTN)(Address + (Segment->Address - Kernel->Base)));
    if (EFI_ERROR (Status)) { return Status; }
  }
  return EFI_SUCCESS;
}
