 else {m[0].NumberOfPages=(owned-0xe0600000ULL)/4096;m[1].Type=EfiLoaderCode;m[1].PhysicalStart=owned;m[1].NumberOfPages=SIZE_256MB/4096;m[2].Type=EfiConventionalMemory;m[2].PhysicalStart=owned+SIZE_256MB;m[2].NumberOfPages=(0xf2600000ULL-m[2].PhysicalStart)/4096;}
