static EFI_STATUS EFIAPI mock_exit(EFI_HANDLE h, UINTN key) {
 (void)h;assert(key==123&&!opens&&live==1);exits++;
 if(mode==RETRY_EXIT&&exits==1)return EFI_INVALID_PARAMETER;
 for(UINTN i=0;i<expected_kernel.Count;i++){
  SEGMENT *s=&expected_kernel.Segments[i];
  assert(!memcmp((VOID*)(UINTN)(owned+s->Address-expected_kernel.Base),kernel_file.data+s->FileOffset,s->FileSize));
 }
