static unsigned run(int scenario,unsigned fail) {
 mode=scenario;fail_pool=fail;allocations=pass_count=crc_count=0;header_bytes=max_read=peak=0;exits=entered=0;current_el=mode==BAD_EL?8:4;
 volatile UINTN tree_size=tree_file.size;if(mode==BAD_ADT)tree_file.size=7;
 if(mode==BAD_HEADER)kernel_file.data[0]^=1;
 info.PixelFormat=mode==BAD_VIDEO?PixelBltOnly:PixelBlueGreenRedReserved8BitPerColor;
 UNIXNU_LOADER_BOOT_REQUEST req={0};req.Volume=(VOID*)1;req.KernelPath=L"\\Payloads\\kernel.macho";req.BootArgs=mode==BAD_ARGS?L"\u0100":L"-v serial=3 cpus=1";
