 if(setjmp(handoff)==0)status=Boot(NULL,&req);
 unsigned calls=allocations;
 int expected=(mode==NORMAL||mode==SHORT_READ||mode==RETRY_EXIT)&&(!fail||fail>calls);
 if(entered!=(unsigned)expected)fprintf(stderr,"mismatch scenario=%d fail=%u calls=%u status=%llx entered=%u\n",mode,fail,calls,status,entered);
 assert(entered==(unsigned)expected&&!opens);
 if(expected){
  assert(live==1&&owned&&max_read==65536);assert(exits==(mode==RETRY_EXIT?2u:1u));
  // The memory-map pool intentionally survives successful EBS. Release it in
  // the harness only after the observed handoff, then reset simulated memory.
  exits=0;for(unsigned i=0;i<128;i++)if(pool_slots[i])FreePool(pool_slots[i]);
  assert(!mprotect((void*)(uintptr_t)owned,SIZE_256MB,PROT_NONE));owned=0;
 }else{assert(EFI_ERROR(status)&&!owned&&!exits);}
 assert(!live&&!pool_bytes);
 if(mode==BAD_HEADER)kernel_file.data[0]^=1;tree_file.size=tree_size;
 printf("scenario=%d fail_pool=%u status=%llx handoff=%u pools=%u peak=%llu\n",mode,fail,status,entered,calls,peak);return calls;
}
